test_suite:
test('type-level: Length of [1,2,3] is 3', () => {
  type T = Length<[1, 2, 3]>;
  const check: T = 3;
  expect(check).toBe(3);
});

test('type-level: Length of [] is 0', () => {
  type T = Length<[]>;
  const check: T = 0;
  expect(check).toBe(0);
});

test('type-level: IsEmpty<[]> is true', () => {
  type T = IsEmpty<[]>;
  const check: T = true;
  expect(check).toBe(true);
});

test('type-level: IsEmpty<[1]> is false', () => {
  type T = IsEmpty<[number]>;
  const check: T = false;
  expect(check).toBe(false);
});

// __hidden__
test('type-level: Length of single element tuple is 1', () => {
  type T = Length<[string]>;
  const check: T = 1;
  expect(check).toBe(1);
});
